text(await tools.exec_command({cmd:"$notesPath = Join-Path (Get-Location) 'notes.md'
$utf8 = New-Object System.Text.UTF8Encoding($false)
$prefix = ''
if (Test-Path -LiteralPath $notesPath) {
  $existing = [System.IO.File]::ReadAllText($notesPath)
  if ($existing.Length -gt 0 -and -not $existing.EndsWith("`n") -and -not $existing.EndsWith("`r")) { $prefix = [Environment]::NewLine }
}
[System.IO.File]::AppendAllText($notesPath, $prefix + 'test from rusha' + [Environment]::NewLine, $utf8)","max_output_tokens":1000}));
